/**
 * @file cropGeometry.ts
 * @description Utility functions for cropping geometry
 */

import * as THREE from 'three';

/**
 * Crop a BufferGeometry based on bounding box
 * Keeps triangles that are entirely within the bounds
 */
export function cropBufferGeometry(
  geometry: THREE.BufferGeometry,
  min: [number, number, number],
  max: [number, number, number]
): THREE.BufferGeometry {
  const positions = geometry.attributes.position;
  const indices = geometry.index;
  
  if (!positions) {
    throw new Error('Geometry must have position attribute');
  }

  const newPositions: number[] = [];
  const newIndices: number[] = [];
  const vertexMap = new Map<number, number>();

  // Check if a vertex is within bounds
  const isVertexInBounds = (index: number): boolean => {
    const x = positions.getX(index);
    const y = positions.getY(index);
    const z = positions.getZ(index);
    return x >= min[0] && x <= max[0] &&
           y >= min[1] && y <= max[1] &&
           z >= min[2] && z <= max[2];
  };

  // Check if all vertices of a triangle are within bounds
  const isTriangleInBounds = (i0: number, i1: number, i2: number): boolean => {
    return isVertexInBounds(i0) && isVertexInBounds(i1) && isVertexInBounds(i2);
  };

  if (indices) {
    // Indexed geometry
    for (let i = 0; i < indices.count; i += 3) {
      const i0 = indices.getX(i);
      const i1 = indices.getX(i + 1);
      const i2 = indices.getX(i + 2);

      if (isTriangleInBounds(i0, i1, i2)) {
        // Add triangle vertices
        for (const idx of [i0, i1, i2]) {
          if (!vertexMap.has(idx)) {
            const newIdx = newPositions.length / 3;
            vertexMap.set(idx, newIdx);
            newPositions.push(
              positions.getX(idx),
              positions.getY(idx),
              positions.getZ(idx)
            );
          }
          newIndices.push(vertexMap.get(idx)!);
        }
      }
    }
  } else {
    // Non-indexed geometry
    for (let i = 0; i < positions.count; i += 3) {
      const i0 = i;
      const i1 = i + 1;
      const i2 = i + 2;

      if (isTriangleInBounds(i0, i1, i2)) {
        newPositions.push(
          positions.getX(i0),
          positions.getY(i0),
          positions.getZ(i0),
          positions.getX(i1),
          positions.getY(i1),
          positions.getZ(i1),
          positions.getX(i2),
          positions.getY(i2),
          positions.getZ(i2)
        );
      }
    }
  }

  // Create new geometry
  const newGeometry = new THREE.BufferGeometry();
  newGeometry.setAttribute('position', new THREE.Float32BufferAttribute(newPositions, 3));

  if (newIndices.length > 0) {
    newGeometry.setIndex(newIndices);
  }

  // Compute normals if original had normals
  if (geometry.attributes.normal) {
    newGeometry.computeVertexNormals();
  }

  return newGeometry;
}

/**
 * Convert BufferGeometry to STL binary format
 */
export function geometryToSTLBinary(geometry: THREE.BufferGeometry): ArrayBuffer {
  // Dynamically import STLExporter
  const { STLExporter } = require('three/addons/exporters/STLExporter.js');
  const exporter = new STLExporter();
  
  // Create a temporary mesh for export
  const mesh = new THREE.Mesh(geometry, new THREE.MeshBasicMaterial());
  const stlString = exporter.parse(mesh);
  
  // Convert ASCII STL to binary
  const lines = stlString.split('\n');
  const vertices: number[] = [];
  const normals: number[] = [];
  
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim();
    if (line.startsWith('facet normal')) {
      const parts = line.split(/\s+/);
      normals.push(
        parseFloat(parts[2]),
        parseFloat(parts[3]),
        parseFloat(parts[4])
      );
    } else if (line.startsWith('vertex')) {
      const parts = line.split(/\s+/);
      vertices.push(
        parseFloat(parts[1]),
        parseFloat(parts[2]),
        parseFloat(parts[3])
      );
    }
  }

  const triangleCount = vertices.length / 9;
  const buffer = new ArrayBuffer(80 + 4 + triangleCount * 50);
  const view = new DataView(buffer);
  
  // Header (80 bytes)
  const header = 'STL Binary Format - Generated by NFLOW';
  for (let i = 0; i < 80; i++) {
    view.setUint8(i, i < header.length ? header.charCodeAt(i) : 0);
  }
  
  // Triangle count (4 bytes)
  view.setUint32(80, triangleCount, true);
  
  // Triangles (50 bytes each: 12 bytes normal + 36 bytes vertices + 2 bytes attribute)
  let offset = 84;
  for (let i = 0; i < triangleCount; i++) {
    const normalIdx = i * 3;
    const vertexIdx = i * 9;
    
    // Normal
    view.setFloat32(offset, normals[normalIdx], true);
    view.setFloat32(offset + 4, normals[normalIdx + 1], true);
    view.setFloat32(offset + 8, normals[normalIdx + 2], true);
    
    // Vertices
    for (let j = 0; j < 9; j++) {
      view.setFloat32(offset + 12 + j * 4, vertices[vertexIdx + j], true);
    }
    
    // Attribute byte count (2 bytes, usually 0)
    view.setUint16(offset + 48, 0, true);
    
    offset += 50;
  }
  
  return buffer;
}
